insert into projects (slug, name, tagline, industry, icon, cover, phone_screen, summary, title, lead, platform, services_label, challenge_title, challenge_text, solution_title, solution_text, features, screens, tech_title, tech, tech_points, why, sort_order) values ('auctionflow', 'AuctionFlow', 'White-label auction platform', 'Auctions', 'ri-auction-line', '/assets/images/projects/auctionflow.jpg', '/assets/images/projects/screens/auctionflow-home.jpg', 'A complete auction platform (bidder app, website and back office) set up under each auction house''s own brand. Live bidding with auto-bids and anti-sniping, hidden reserves, staff roles, and payment by EcoCash, OneMoney or InnBucks. Also built as Beta Auction.', 'AuctionFlow: your own auction app, in every bidder''s pocket.', 'A complete auction platform, with a bidder app, a website and a back office, set up for each auction house under its own name.', 'Android, iPhone & web', null, null, null, null, null, '[]'::jsonb, '[{"image":"/assets/images/projects/auctionflow/03-home.jpg","caption":"Your auctions, on every phone"},{"image":"/assets/images/projects/auctionflow/05-lot.jpg","caption":"Every lot, in detail"},{"image":"/assets/images/projects/auctionflow/06-bidding.jpg","caption":"Bid now or auto-bid"},{"image":"/assets/images/projects/auctionflow/10-mobile-money.jpg","caption":"Pay by EcoCash, OneMoney or InnBucks"},{"image":"/assets/images/projects/auctionflow/11-admin.jpg","caption":"Run the auction house from a phone"},{"image":"/assets/images/projects/auctionflow/14-reserve.jpg","caption":"Hidden reserves, your decision"}]'::jsonb, null, '{}'::text[], '{}'::text[], '[]'::jsonb, 1);
insert into projects (slug, name, tagline, industry, icon, cover, phone_screen, summary, title, lead, platform, services_label, challenge_title, challenge_text, solution_title, solution_text, features, screens, tech_title, tech, tech_points, why, sort_order) values ('proqit', 'Proqit', 'Building-materials ordering', 'Construction', 'ri-building-2-line', '/assets/images/projects/proqit.jpg', null, 'A building-materials app built around the customer''s building project, not a shopping cart. Guest, trade and bulk pricing, delivery priced by load and route, multi-supplier sourcing, and a WhatsApp assistant that answers in local languages.', 'Proqit: building materials, procured like a pro.', 'A custom app for a Zimbabwean building-materials supplier, built around the customer''s building project instead of a shopping cart.', 'Android & iPhone', 'Mobile app, admin, integrations', 'Customers don''t think in shopping carts.', 'Proqit sells building materials, but it didn''t want to be another online hardware shop. Its goal is to be the easiest way to source materials for a whole building project. Customers think “I''m putting up a house in Bulawayo and I''m at the roofing stage.” A generic e-commerce template can''t handle that.', 'A system built around how Proqit works.', 'We built an app where every order belongs to a building project and its stage, prices follow the customer''s tier, and delivery is priced by the real load and route. The owner runs orders, drivers, suppliers and quotes from the same app.', '[{"icon":"ri-building-2-line","title":"Projects at the centre","text":"Each build has its stage (foundation, walling, roofing), its documents, its account manager and every order filed against it."},{"icon":"ri-file-upload-line","title":"Plans and quotes to beat","text":"Guests send a building plan, bill of quantities or a competitor''s quote, and it lands in the team''s leads pipeline."},{"icon":"ri-price-tag-3-line","title":"Pricing tiers","text":"Guest, trade and bulk prices, applied automatically."},{"icon":"ri-truck-line","title":"Delivery by load and route","text":"Bags of cement go by bakkie, roof sheets by flatbed, sand by tipper, each priced accordingly."},{"icon":"ri-lock-password-line","title":"Delivery codes","text":"6-digit codes, so goods are only handed to the right person."},{"icon":"ri-whatsapp-line","title":"WhatsApp assistant","text":"Answers customers in local languages and captures quote requests as leads."}]'::jsonb, '[{"image":"/assets/images/projects/proqit/01-projects.jpg","caption":"Projects at the centre"},{"image":"/assets/images/projects/proqit/02-upload-plans.jpg","caption":"Upload plans or a quote to beat"},{"image":"/assets/images/projects/proqit/04-pricing.jpg","caption":"Guest, trade and bulk pricing"},{"image":"/assets/images/projects/proqit/07-delivery-quote.jpg","caption":"Delivery priced by load and route"},{"image":"/assets/images/projects/proqit/10-admin.jpg","caption":"Admin mode in the same app"},{"image":"/assets/images/projects/proqit/14-sourcing.jpg","caption":"Multi-supplier sourcing"}]'::jsonb, 'Business rules live in the database, not the screen.', array['React Native', 'Expo', 'Supabase', 'PostgreSQL', 'WhatsApp Cloud API', 'OpenAI', 'Google Maps'], array['React Native and Expo: one codebase for Android and iOS', 'Supabase: PostgreSQL, Auth, Storage, Edge Functions and realtime updates', 'Row-level security on every table, so customers and drivers only ever see their own data', 'Orders re-priced on the server, so totals on the phone can''t be tampered with', 'Multi-supplier sourcing that picks the cheapest mix of goods plus delivery', 'A delivery engine that plans routes and picks vehicles by weight, length or volume', 'WhatsApp Cloud API with AI replies, while prices always come from the live catalogue'], '[{"icon":"ri-git-branch-line","title":"Follows the business","text":"The software follows project-centric procurement instead of forcing it into a shop template."},{"icon":"ri-database-2-line","title":"Rules in one place","text":"Pricing, sourcing, delivery and permissions live in the database, so a web dashboard can reuse them later."},{"icon":"ri-map-pin-line","title":"Local realities","text":"WhatsApp-first customers, local languages, and delivery zones that grow town by town."},{"icon":"ri-key-2-line","title":"Owned by the client","text":"No per-seat SaaS fees, and the client owns the system."}]'::jsonb, 2);
insert into projects (slug, name, tagline, industry, icon, cover, phone_screen, summary, title, lead, platform, services_label, challenge_title, challenge_text, solution_title, solution_text, features, screens, tech_title, tech, tech_points, why, sort_order) values ('winno-brix', 'Winno Brix', 'Block-yard management', 'Construction', 'ri-stack-line', '/assets/images/projects/winno-brix.jpg', null, 'A block yard run from a phone: production batches from moulding to curing, stock by product, quotes and orders, delivery planning, invoices, reports and staff permissions.', 'Winno Brix: a block yard, run from a phone.', 'Production batches from moulding to curing, stock by product, quotes and orders, delivery planning, invoices, reports and staff permissions, in one app.', 'Android & iPhone', null, null, null, null, null, '[]'::jsonb, '[{"image":"/assets/images/projects/winno-brix/01-dashboard.jpg","caption":"The whole yard at a glance"},{"image":"/assets/images/projects/winno-brix/02-production.jpg","caption":"Every batch, tracked"},{"image":"/assets/images/projects/winno-brix/03-stock.jpg","caption":"Stock that always adds up"},{"image":"/assets/images/projects/winno-brix/05-delivery-plan.jpg","caption":"Fewest trips, full trucks"},{"image":"/assets/images/projects/winno-brix/08-reports.jpg","caption":"Know your profit"},{"image":"/assets/images/projects/winno-brix/09-permissions.jpg","caption":"The right access for each person"}]'::jsonb, null, '{}'::text[], '{}'::text[], '[]'::jsonb, 3);
insert into projects (slug, name, tagline, industry, icon, cover, phone_screen, summary, title, lead, platform, services_label, challenge_title, challenge_text, solution_title, solution_text, features, screens, tech_title, tech, tech_points, why, sort_order) values ('medcompare', 'Med Compare', 'Medicine price comparison', 'Health', 'ri-capsule-line', '/assets/images/projects/medcompare.jpg', null, 'Compare medicine prices across pharmacies, cheapest first, and find the one pharmacy that covers a whole prescription for the lowest total. Users save the medicines they buy often and report new prices with a photo of the receipt.', 'Med Compare: stop overpaying for your medicine.', 'Compare medicine prices across pharmacies, cheapest first, and find the one pharmacy that covers a whole prescription for the lowest total.', 'Android & iPhone', null, null, null, null, null, '[]'::jsonb, '[{"image":"/assets/images/projects/medcompare/02-search.jpg","caption":"Find any registered medicine"},{"image":"/assets/images/projects/medcompare/03-compare.jpg","caption":"Every pharmacy, cheapest first"},{"image":"/assets/images/projects/medcompare/04-cart.jpg","caption":"Add your whole list"},{"image":"/assets/images/projects/medcompare/05-best-pharmacy.jpg","caption":"One trip, lowest total"},{"image":"/assets/images/projects/medcompare/06-saved.jpg","caption":"Track what you buy often"},{"image":"/assets/images/projects/medcompare/08-submit.jpg","caption":"Report a price with a photo of the receipt"}]'::jsonb, null, '{}'::text[], '{}'::text[], '[]'::jsonb, 4);
insert into projects (slug, name, tagline, industry, icon, cover, phone_screen, summary, title, lead, platform, services_label, challenge_title, challenge_text, solution_title, solution_text, features, screens, tech_title, tech, tech_points, why, sort_order) values ('rentr', 'rentr', 'Property rentals', 'Property', 'ri-home-4-line', '/assets/images/projects/rentr.jpg', '/assets/images/projects/screens/rentr-home.jpg', 'Rooms, cottages, flats and houses to rent in one app, with the photos, the rent and what''s included. Tenants message the landlord and arrange a viewing in the same chat, and landlords list a place in minutes from their phone.', 'rentr: find your next place, right from your phone.', 'Rooms, cottages, flats and houses to rent in one app. Tenants message the landlord and arrange a viewing in the same chat, and landlords list a place in minutes.', 'Android & iPhone', null, null, null, null, null, '[]'::jsonb, '[{"image":"/assets/images/projects/rentr/01-explore.jpg","caption":"Every place to rent, in one list"},{"image":"/assets/images/projects/rentr/04-listing.jpg","caption":"See the place properly"},{"image":"/assets/images/projects/rentr/06-whats-there.jpg","caption":"Know what you''re getting"},{"image":"/assets/images/projects/rentr/08-viewings.jpg","caption":"Arrange a viewing in the chat"},{"image":"/assets/images/projects/rentr/10-stay-safe.jpg","caption":"See it before you pay"},{"image":"/assets/images/projects/rentr/11-landlords.jpg","caption":"List a place in minutes"}]'::jsonb, null, '{}'::text[], '{}'::text[], '[]'::jsonb, 5);
insert into projects (slug, name, tagline, industry, icon, cover, phone_screen, summary, title, lead, platform, services_label, challenge_title, challenge_text, solution_title, solution_text, features, screens, tech_title, tech, tech_points, why, sort_order) values ('bushveld-figtree', 'Bushveld Figtree', 'Hardware point of sale and stock', 'Retail', 'ri-tools-line', '/assets/images/projects/bushveld.jpg', null, 'The point of sale and back office for a hardware store. Staff ring up sales and record change owed, airtime, EcoCash, ZESA and the day''s takings; managers track stock with reorder alerts, see reports and set what each role can do. It keeps selling with no signal and syncs when it''s back online.', 'Bushveld Figtree: the whole hardware store, run from one phone.', 'The point of sale and back office for a hardware store, with stock, reports and staff roles, that keeps selling with no signal.', 'Android & iPhone', null, null, null, null, null, '[]'::jsonb, '[{"image":"/assets/images/projects/bushveld-figtree/02-home.jpg","caption":"Every counter job, one tap away"},{"image":"/assets/images/projects/bushveld-figtree/03-new-sale.jpg","caption":"Ring up a sale in seconds"},{"image":"/assets/images/projects/bushveld-figtree/07-ecocash.jpg","caption":"Every wallet movement, balanced"},{"image":"/assets/images/projects/bushveld-figtree/09-reports.jpg","caption":"See what''s selling"},{"image":"/assets/images/projects/bushveld-figtree/12-offline.jpg","caption":"No signal? Keep selling"},{"image":"/assets/images/projects/bushveld-figtree/13-stock.jpg","caption":"Know exactly when to reorder"}]'::jsonb, null, '{}'::text[], '{}'::text[], '[]'::jsonb, 6);
insert into projects (slug, name, tagline, industry, icon, cover, phone_screen, summary, title, lead, platform, services_label, challenge_title, challenge_text, solution_title, solution_text, features, screens, tech_title, tech, tech_points, why, sort_order) values ('ntafa', 'NTAFA', 'Football league app', 'Sport', 'ri-football-line', '/assets/images/projects/ntafa.jpg', '/assets/images/projects/screens/ntafa-home.jpg', 'The official app of the Ntabazinduna Football Association. Fans get fixtures, results, the log and squads; officials run fixtures, referee appointments, results, player registration, suspensions and season subscriptions.', 'NTAFA: your league, in your pocket.', 'The official app of the Ntabazinduna Football Association, for fans, clubs, referees and the officials who run the league.', 'Android & iPhone', null, null, null, null, null, '[]'::jsonb, '[{"image":"/assets/images/projects/ntafa/01-home.jpg","caption":"Everything in one place"},{"image":"/assets/images/projects/ntafa/02-fixtures.jpg","caption":"Never miss a kick-off"},{"image":"/assets/images/projects/ntafa/04-table.jpg","caption":"Where does your club stand?"},{"image":"/assets/images/projects/ntafa/05-club.jpg","caption":"Follow your club"},{"image":"/assets/images/projects/ntafa/09-officials.jpg","caption":"Run the league from your phone"},{"image":"/assets/images/projects/ntafa/10-referees.jpg","caption":"Results straight from the pitch"}]'::jsonb, null, '{}'::text[], '{}'::text[], '[]'::jsonb, 7);
insert into services (slug, name, icon, nav_text, list_text, summary, bullets, card_bullets, seen_in, title, lead, hero_phones, included_title, included, steps_title, steps, built_with, related, related_label, faq_title, faq, sort_order) values ('mobile-apps', 'Mobile Apps', 'ri-smartphone-line', 'Android and iPhone from one codebase', 'Android and iPhone', 'Android and iPhone apps from one codebase, with an admin side your team can run from the same phone.', array['Customer and staff apps in one', 'Listed on Google Play and the App Store under your name', 'Live updates for prices, bids and scores'], array['Customer and staff apps in one', 'Listed under your name', 'Live updates for prices, bids and scores'], array['auctionflow', 'proqit', 'winno-brix', 'medcompare', 'rentr', 'bushveld-figtree', 'ntafa'], 'Mobile apps for Android and iPhone.', 'One codebase for both platforms, with an admin side your team can run from the same phone, all built around how your business works.', array['rentr', 'auctionflow', 'ntafa'], 'Everything your app needs', '[{"icon":"ri-smartphone-line","title":"Android and iPhone","text":"One React Native codebase runs on both, which keeps building and upkeep costs down."},{"icon":"ri-admin-line","title":"Admin mode built in","text":"Your team runs orders, listings, results or payments from the same app."},{"icon":"ri-flashlight-line","title":"Live updates","text":"Prices, bids, scores and countdowns update on every phone at the same moment."},{"icon":"ri-wallet-3-line","title":"Mobile money","text":"EcoCash, OneMoney and InnBucks built into checkout, plus bank and cash options."},{"icon":"ri-whatsapp-line","title":"WhatsApp","text":"Assistants and alerts right where your customers already talk to you."},{"icon":"ri-store-2-line","title":"Under your name","text":"Listed on Google Play and the App Store with your name, logo and colours."}]'::jsonb, 'From idea to App Store', '[{"title":"Map how you work","text":"We learn how your business runs: your customers, your staff, your payments and your rules."},{"title":"Design the screens","text":"Flows and screens for every kind of user, tested with you before any code is written."},{"title":"Build and test","text":"One codebase for Android and iPhone, with security checked in the database, not just hidden in the app."},{"title":"Launch and grow","text":"We publish to the app stores under your name, then keep improving the app as you grow."}]'::jsonb, array['React Native', 'Expo', 'Supabase', 'PostgreSQL', 'PowerSync'], array['proqit', 'winno-brix', 'ntafa'], 'Mobile apps we built', 'Questions about mobile apps', '[{"question":"Do you build for both Android and iPhone?","answer":"Yes. We build with React Native and Expo, so one codebase runs on both platforms. That keeps the cost of building and maintaining the app down."},{"question":"Can my staff manage things from the app?","answer":"Yes. Most of our apps include an admin mode in the same app, so your team can run orders, listings, payments or results from a phone."},{"question":"Will the app carry our name?","answer":"Yes. It''s listed on Google Play and the App Store under your name, with your logo and colours throughout."},{"question":"Who owns the app?","answer":"You do. Your customers and your data live in a system that belongs to you, with no per-seat fees."},{"question":"What happens after launch?","answer":"We stay on to support the app, release updates and add features as your business grows."}]'::jsonb, 1);
insert into services (slug, name, icon, nav_text, list_text, summary, bullets, card_bullets, seen_in, sort_order) values ('web-apps', 'Web Apps & Back Offices', 'ri-window-line', 'Websites, dashboards and admin tools', 'Websites, dashboards, admin tools', 'Websites, online catalogues and back offices for the people who run the business day to day.', array['Public website and online catalogue', 'Back office that runs on any computer', 'Staff roles, so everyone sees only what their job needs'], array['Public website and online catalogue', 'Back office on any computer', 'Staff roles and permissions'], array['auctionflow'], 2);
insert into services (slug, name, icon, nav_text, list_text, summary, bullets, card_bullets, seen_in, sort_order) values ('ux-ui-design', 'UX/UI Design', 'ri-pen-nib-line', 'Screens people understand first time', 'Flows, screens, design systems', 'Screens designed around the people using them, from the first sketch to a full design handoff.', array['User flows and wireframes', 'App and web interface design', 'Design systems your developers can build from'], array['User flows and wireframes', 'App and web interface design', 'Design systems for developers'], array['auctionflow', 'proqit', 'winno-brix', 'medcompare', 'rentr', 'bushveld-figtree', 'ntafa'], 3);
insert into services (slug, name, icon, nav_text, list_text, summary, bullets, card_bullets, seen_in, sort_order) values ('integrations', 'Integrations', 'ri-plug-line', 'Mobile money, WhatsApp and AI', 'Mobile money, WhatsApp, AI', 'Connect your app to the services your customers already use.', array['EcoCash, OneMoney and InnBucks payments', 'WhatsApp assistants that capture leads', 'AI replies that use your live prices, never made-up ones'], array['EcoCash, OneMoney and InnBucks', 'WhatsApp assistants that capture leads', 'AI replies grounded in your data'], array['auctionflow', 'proqit'], 4);
insert into services (slug, name, icon, nav_text, list_text, summary, bullets, card_bullets, seen_in, sort_order) values ('support-hosting', 'Support & Hosting', 'ri-server-line', 'Updates and growth after launch', 'After launch', 'We stay on after launch to keep your app running and growing with your business.', array['Updates and new features as you grow', 'App store releases handled for you', 'Help when your team needs it'], array['Updates and new features', 'App store releases handled', 'Help when your team needs it'], '{}'::text[], 5);
insert into process_steps (title, text, sort_order) values ('Discovery & Planning', 'We begin by understanding your business goals, target audience and project requirements: research, stakeholder interviews and clear objectives, so everyone is aligned.', 1);
insert into process_steps (title, text, sort_order) values ('Strategy & Design', 'Our creative and technical teams develop user-centred designs and a roadmap, including wireframes, prototypes and the technical architecture your app needs.', 2);
insert into process_steps (title, text, sort_order) values ('Development & Build', 'We bring the designs to life in clean, scalable code, working in short iterations with regular testing for quality and performance on every platform.', 3);
insert into process_steps (title, text, sort_order) values ('Testing & Quality Assurance', 'Rigorous testing finds and fixes bugs and polishes usability, so the experience is right before anyone outside the team sees it.', 4);
insert into process_steps (title, text, sort_order) values ('Launch & Deployment', 'We deploy carefully to live environments with minimal disruption, and provide training and documentation for your team as needed.', 5);
insert into process_steps (title, text, sort_order) values ('Support & Scaling', 'After launch we keep supporting and maintaining your app, adapting and scaling it as your business grows.', 6);
insert into posts (slug, title, excerpt, lead, industry, project_slug, cover, cover_alt, body, sort_order) values ('your-next-buyer-is-on-their-phone', 'Your next buyer isn''t standing in the yard. They''re on their phone.', 'Most auction houses still sell the way they did twenty years ago: a printed catalogue, a viewing day, and a crowd that has to be there in person. Everyone who can''t get to the yard on sale day is a bid you never see.', 'Why auction houses that still sell only on sale day are leaving bids on the table, and what a branded auction app changes.', 'Auctions', 'auctionflow', '/assets/images/insights/insight-auctionflow.jpg', 'AuctionFlow back office dashboard', '[{"type":"intro","text":"Most auction houses in Zimbabwe still sell the way they did twenty years ago: a printed catalogue, a viewing day, and a crowd that has to be there in person. Everyone who can''t get to the yard on sale day is a bid you never see."},{"type":"p","text":"So we built AuctionFlow: online auctions, simplified. It''s a complete auction platform, with a bidder app, a website and a back office, set up for each auction house under its own name. Your logo, your colours, your listing on Google Play and the App Store, your web address. Your bidders only ever see your brand."},{"type":"h2","text":"What your bidders get"},{"type":"ul","items":["A full online catalogue: photos, specs, location and a live countdown for every lot","Bid now, or set a maximum and let the app bid for them one step at a time","Anti-sniping: a late bid extends the lot, so nobody wins by refreshing at the last second","Instant alerts when they''re outbid, when a lot is ending, and when they win","Buyer''s premium and VAT worked out on every win, so there are no surprises at the cashier","Pay by EcoCash, OneMoney or InnBucks in the app, or by bank transfer or cash at your office"]},{"type":"images","images":[{"src":"/assets/images/insights/auctionflow-10-mobile-money.jpg","alt":"Paying by EcoCash, OneMoney or InnBucks in AuctionFlow"},{"src":"/assets/images/insights/auctionflow-01-white-label.jpg","alt":"AuctionFlow runs under each auction house''s own brand"}]},{"type":"h2","text":"What your team gets"},{"type":"ul","items":["A full admin mode on the phone, and a back office on any computer: create a sale, photograph lots in the yard and publish","Hidden reserves: bids that end below reserve wait for your decision, accept or decline","Every bid and every bidder''s secret maximum, visible to staff only","Payments, proofs of payment and collections tracked lot by lot","Unsold lots relisted into the next sale automatically, held back until you approve them","Staff roles (auction manager, cashier, collections, viewer), so each person only sees and changes what their job needs"]},{"type":"h2","text":"Your brand, not ours"},{"type":"p","text":"Your name and logo on the app, the website and every message bidders receive. Your colours throughout. Listed in the app stores under your name, on your own web address, with your bank, mobile money and collection details. Your bidders and your data live in a system that belongs to you."},{"type":"h2","text":"Built to be trusted"},{"type":"ul","items":["Prices and countdowns update live on every phone, so everyone sees the same sale at the same moment","Two people bidding in the same second can''t break it: every bid is checked and recorded centrally","Bidders never see your reserves or anyone else''s maximum bid","Lots close on time by themselves, winners are told straight away, and watchers get an \"ending soon\" reminder","Works on Android, iPhone and any computer"]},{"type":"h2","text":"Why it matters"},{"type":"quote","text":"More bidders means more competition, and better prices for your sellers."},{"type":"p","text":"An online sale reaches bidders in Harare, Bulawayo, Mutare and the diaspora, not just whoever turns up on the day. Sales run around the clock, and staff time goes into the lots, not the paperwork. It''s built for Zimbabwe, with mobile money, USD pricing, VAT and WhatsApp contact for every buyer, and there''s no per-sale platform commission."},{"type":"p","text":"If you run an auction house and want your own branded auction app and website, [get in touch](/contact). And if you need another custom app or business system built around how you work, we''d like to hear about that too."}]'::jsonb, 1);
insert into posts (slug, title, excerpt, lead, industry, project_slug, cover, cover_alt, body, sort_order) values ('no-two-businesses-are-the-same', 'No two businesses are the same. So why should the systems that run them be?', 'Customers don''t think in shopping carts. They think “I''m putting up a house in Bulawayo and I''m at the roofing stage.” A generic e-commerce template can''t handle that, so we built around how Proqit actually works.', null, 'Construction', 'proqit', '/assets/images/insights/insight-proqit.jpg', 'Proqit', null, 2);
insert into posts (slug, title, excerpt, lead, industry, project_slug, cover, cover_alt, body, sort_order) values ('run-the-league-from-your-phone', 'Run the league from your phone.', 'Officials make the fixture list, appoint referees and enter results in minutes. Referees send the score straight from the pitch, and the association confirms it before it counts.', null, 'Sport', 'ntafa', '/assets/images/insights/insight-ntafa.jpg', 'NTAFA', null, 3);
